// 课程内容：依据公开 HSK 大纲编写，对话、例句均为本项目原创
const lessons=[{"id":"QH-001","level":"HSK 1","title":"你好，我叫 Alex","scene":"第一次见面","vocab":["你","好","叫","是","名字","学生","老师","认识"],"dialogue":[{"s":"林","t":"你好！我叫林悦。你叫什么名字？"},{"s":"安","t":"你好！我叫 Alex，很高兴认识你。"},{"s":"林","t":"我也很高兴认识你。你是学生吗？"},{"s":"安","t":"是，我是学生。你是老师吗？"},{"s":"林","t":"对，我是中文老师。"}],"grammar":{"name":"是；吗","pattern":"我是 + 身份。你是 …… 吗？","explain":"“是”表示判断；“吗”放在句尾把陈述句变成疑问句。","examples":["我是学生。","你是老师吗？"],"practice":{"q":"哪一句是正确的问题？","opts":["你是学生吗？","你吗是学生？"],"ans":0}},"listening":{"q":"安的身份是什么？","audio":"你好！我叫 Alex，我是学生。","opts":["他是老师","他是学生","他是医生"],"ans":1},"shadowing":"你好！我叫 Alex，很高兴认识你。","quiz":{"q":"我 ___ 学生。","opts":["是","好","叫"],"ans":0,"fb":"“是”表示判断：我是学生。"}},{"id":"QH-002","level":"HSK 1","title":"你是哪国人","scene":"认识新同学","vocab":["哪","国","人","中国","美国","谁","都","吗"],"dialogue":[{"s":"林","t":"你是哪国人？"},{"s":"安","t":"我是美国人。你呢？"},{"s":"林","t":"我是中国人。你们班有多少美国人？"},{"s":"安","t":"我们班有三个美国人，我们都是同学。"},{"s":"林","t":"那位老师是谁？"},{"s":"安","t":"她是王老师，也是中国人。"}],"grammar":{"name":"哪；谁","pattern":"你是哪国人？/ 那个人是谁？","explain":"“哪”问类别中的哪一个；“谁”问具体是哪个人。","examples":["你是哪国人？","那位老师是谁？"],"practice":{"q":"想问“哪个国家”，应该用：","opts":["你是哪国人？","你是中国人谁？"],"ans":0}},"listening":{"q":"班里有多少美国人？","audio":"我们班有三个美国人，我们都是同学。","opts":["两个","三个","四个"],"ans":1},"shadowing":"我是美国人，我们班有三个美国人。","quiz":{"q":"你是 ___ 国人？","opts":["哪","谁","吗"],"ans":0,"fb":"问国籍用“哪国人”。"}},{"id":"QH-003","level":"HSK 1","title":"这是我的老师","scene":"介绍身边的人","vocab":["这","那","的","我","他","她","家","朋友"],"dialogue":[{"s":"安","t":"王老师，这是我朋友林悦。"},{"s":"王","t":"你好，林悦！你是 Alex 的同学吗？"},{"s":"林","t":"是的，我们都是中文班的学生。"},{"s":"王","t":"那位是你的家人吗？"},{"s":"安","t":"不是，那是我的朋友，他是美国人。"},{"s":"王","t":"好的，欢迎你们！"}],"grammar":{"name":"这 / 那；的","pattern":"这是 + 人/物；我的 + 人/物","explain":"“这”指近的，“那”指远的；“的”连接所属关系。","examples":["这是我的老师。","那是他的书。"],"practice":{"q":"“___ 我的老师”介绍身边的人，应该用：","opts":["这是","那是"],"ans":0}},"listening":{"q":"远处那个人是谁？","audio":"那是我的朋友，他是美国人。","opts":["安的家人","安的朋友","王老师"],"ans":1},"shadowing":"这是我的老师，那是我的朋友。","quiz":{"q":"这 ___ 我的老师。","opts":["是","的","那"],"ans":0,"fb":"介绍人时说“这是……”。"}},{"id":"QH-004","level":"HSK 1","title":"现在几点","scene":"约定见面时间","vocab":["现在","点","分","半","几","时间","见面","明天"],"dialogue":[{"s":"安","t":"现在几点了？"},{"s":"林","t":"现在三点十分。"},{"s":"安","t":"我们明天几点见面？"},{"s":"林","t":"明天上午九点半，可以吗？"},{"s":"安","t":"可以，九点半见！"},{"s":"林","t":"好，明天见！"}],"grammar":{"name":"几；点；分","pattern":"几点了？/ X 点 Y 分","explain":"问时间用“几点”；整点加分钟说“X 点 Y 分”，半点说“X 点半”。","examples":["现在三点十分。","我们九点半见面。"],"practice":{"q":"“9:30”正确说法是：","opts":["九点半","九点二"],"ans":0}},"listening":{"q":"他们明天几点见面？","audio":"明天上午九点半，可以吗？","opts":["九点","九点半","十点"],"ans":1},"shadowing":"明天上午九点半，可以吗？","quiz":{"q":"现在 ___ 点了？","opts":["几","什么","怎么"],"ans":0,"fb":"问钟点用“几点”。"}},{"id":"QH-005","level":"HSK 1","title":"我想喝茶","scene":"咖啡店点单","vocab":["想","要","喝","茶","咖啡","杯","水","谢谢"],"dialogue":[{"s":"店","t":"你好！你想喝什么？"},{"s":"安","t":"我想喝茶，要一杯绿茶。"},{"s":"店","t":"好的。你呢？"},{"s":"林","t":"我要一杯咖啡，谢谢。"},{"s":"店","t":"一杯绿茶，一杯咖啡，请稍等。"},{"s":"安","t":"谢谢！"}],"grammar":{"name":"想 + 动词；要","pattern":"我想喝 + 饮料。/ 我要一杯 + 饮料。","explain":"“想 + 动词”说愿望；“要”更直接，点单时用。","examples":["我想喝茶。","我要一杯咖啡。"],"practice":{"q":"在咖啡店点单最自然的说法是：","opts":["我要一杯咖啡。","我咖啡一杯。"],"ans":0}},"listening":{"q":"安想喝什么？","audio":"我想喝茶，要一杯绿茶。","opts":["咖啡","绿茶","水"],"ans":1},"shadowing":"我想喝茶，要一杯绿茶，谢谢。","quiz":{"q":"我 ___ 喝茶。","opts":["想","杯","喝"],"ans":0,"fb":"“想 + 动词”表示愿望。"}},{"id":"QH-006","level":"HSK 1","title":"今天星期几","scene":"安排一周活动","vocab":["今天","星期","几","号","月","年","上午","下午"],"dialogue":[{"s":"安","t":"今天星期几？"},{"s":"林","t":"今天星期二，九月二十九号。"},{"s":"安","t":"我们这个星期有考试吗？"},{"s":"林","t":"没有，考试是下个星期一。"},{"s":"安","t":"那我们星期五下午去公园吧。"},{"s":"林","t":"好主意，星期五下午见！"}],"grammar":{"name":"日期与星期问答","pattern":"今天星期几？/ 今天是 X 月 X 号，星期 X。","explain":"中文日期从大到小：年 → 月 → 号；星期一到六用数字，日用“日/天”。","examples":["今天星期二。","今天是九月二十九号。"],"practice":{"q":"正确的日期顺序是：","opts":["二零二六年九月二十九号","九月二零二六年二十九号"],"ans":0}},"listening":{"q":"考试在哪一天？","audio":"没有，考试是下个星期一。","opts":["这个星期二","下个星期一","星期五"],"ans":1},"shadowing":"今天星期二，九月二十九号。","quiz":{"q":"今天星期 ___ ？","opts":["几","哪","谁"],"ans":0,"fb":"问星期用“星期几”。"}},{"id":"QH-007","level":"HSK 1","title":"我家有三个人","scene":"介绍家庭","vocab":["家","有","口","爸爸","妈妈","个","三","爱"],"dialogue":[{"s":"林","t":"你家有几口人？"},{"s":"安","t":"我家有三口人：爸爸、妈妈和我。"},{"s":"林","t":"你爸爸妈妈做什么工作？"},{"s":"安","t":"我爸爸是医生，我妈妈是老师。"},{"s":"林","t":"你们一家人关系好吗？"},{"s":"安","t":"很好，我很爱我的家。"}],"grammar":{"name":"有；数量 + 量词","pattern":"我家有 + 数量 + 量词 + 人。","explain":"家庭成员用“口”或“个”作量词；“有”表示拥有。","examples":["我家有三口人。","我有一个哥哥。"],"practice":{"q":"问家里人数，应该说：","opts":["你家有几口人？","你家谁是几口人？"],"ans":0}},"listening":{"q":"安的妈妈做什么工作？","audio":"我妈妈是老师。","opts":["医生","老师","学生"],"ans":1},"shadowing":"我家有三口人：爸爸、妈妈和我。","quiz":{"q":"我家 ___ 三口人。","opts":["有","是","在"],"ans":0,"fb":"表示拥有用“有”。"}},{"id":"QH-008","level":"HSK 1","title":"我在学校学习","scene":"介绍日常地点","vocab":["在","学校","学习","工作","公司","医院","哪儿","大学"],"dialogue":[{"s":"林","t":"你在哪儿学习？"},{"s":"安","t":"我在学校学习中文。"},{"s":"林","t":"你妈妈呢？她在哪儿工作？"},{"s":"安","t":"她在医院工作。"},{"s":"林","t":"你爸爸也在医院工作吗？"},{"s":"安","t":"不，他在一家公司工作。"}],"grammar":{"name":"在 + 地点 + 动作","pattern":"我在 + 地点 + 动词。","explain":"“在”先说明地点，再说动作：在学校学习、在公司工作。","examples":["我在学校学习。","她在医院工作。"],"practice":{"q":"正确的语序是：","opts":["我在学校学习。","我学习在学校。"],"ans":0}},"listening":{"q":"安的妈妈在哪里工作？","audio":"她在医院工作。","opts":["学校","公司","医院"],"ans":2},"shadowing":"我在学校学习中文，她在医院工作。","quiz":{"q":"我 ___ 学校学习。","opts":["在","是","有"],"ans":0,"fb":"地点前用“在”。"}},{"id":"QH-009","level":"HSK 1","title":"商店里有苹果","scene":"在商店找东西","vocab":["商店","里","上","下","苹果","水果","买","东西"],"dialogue":[{"s":"安","t":"请问，苹果在哪儿？"},{"s":"店","t":"苹果在商店里面，桌子上。"},{"s":"安","t":"香蕉在哪儿？"},{"s":"店","t":"香蕉在苹果旁边。"},{"s":"安","t":"好的，我想买三个苹果。"},{"s":"店","t":"好，请拿好。"}],"grammar":{"name":"里 / 上 / 下；有","pattern":"地点 + 里/上/下 + 有 + 东西。","explain":"用“有”说某处存在某物，方位词说明具体位置。","examples":["商店里有苹果。","桌子上有书。"],"practice":{"q":"“包里有书”说明：","opts":["书在包的里面","书在包的上面"],"ans":0}},"listening":{"q":"苹果在哪里？","audio":"苹果在商店里面，桌子上。","opts":["桌子上","商店外面","家里"],"ans":0},"shadowing":"商店里有很多水果，苹果在桌子上。","quiz":{"q":"商店里 ___ 苹果。","opts":["有","是","在"],"ans":0,"fb":"存在句用“有”。"}},{"id":"QH-010","level":"HSK 1","title":"明天天气怎么样","scene":"查看天气并安排活动","vocab":["天气","怎么样","很","太","冷","热","下雨","不"],"dialogue":[{"s":"安","t":"明天天气怎么样？"},{"s":"林","t":"天气预报说明天下雨。"},{"s":"安","t":"那我们的公园计划怎么办？"},{"s":"林","t":"如果不热也不太冷，我们可以去博物馆。"},{"s":"安","t":"好主意！博物馆里不冷不热。"},{"s":"林","t":"那就这么定了。"}],"grammar":{"name":"怎么样；很 / 不太","pattern":"天气怎么样？/ 很热。/ 不太冷。","explain":"“怎么样”问情况；“很”表程度高，“不太”表程度不高。","examples":["今天很热。","明天不太冷。"],"practice":{"q":"“有一点热但不是很热”可以说：","opts":["不太热","太热"],"ans":0}},"listening":{"q":"明天天气怎么样？","audio":"天气预报说明天下雨。","opts":["很热","下雨","很冷"],"ans":1},"shadowing":"今天很热，明天不太冷，可能下雨。","quiz":{"q":"明天天气 ___ ？","opts":["怎么样","什么","几"],"ans":0,"fb":"问情况用“怎么样”。"}},{"id":"QH-011","level":"HSK 2","title":"我坐地铁上班","scene":"早晨通勤","vocab":["怎么","坐","地铁","公交","上班","快","远","每"],"dialogue":[{"s":"林","t":"你怎么去上班？"},{"s":"安","t":"我坐地铁上班。你呢？"},{"s":"林","t":"我家离公司远，我每天坐公交。"},{"s":"安","t":"地铁比公交快多了，你可以试试。"},{"s":"林","t":"好，我明天试试坐地铁。"},{"s":"安","t":"十站，大概二十分钟，很快的。"}],"grammar":{"name":"怎么；坐 + 交通工具","pattern":"你怎么去 + 地点？/ 我坐 + 交通工具。","explain":"“怎么”问方式；乘坐交通用“坐 + 工具”。","examples":["你怎么去上班？","我坐地铁上班。"],"practice":{"q":"想问交通方式，应该说：","opts":["你怎么去上班？","你坐什么怎么上班？"],"ans":0}},"listening":{"q":"林平时怎么去公司？","audio":"我家离公司远，我每天坐公交。","opts":["坐地铁","坐公交","走路"],"ans":1},"shadowing":"我坐地铁上班，地铁比公交快多了。","quiz":{"q":"你 ___ 去上班？","opts":["怎么","什么","哪"],"ans":0,"fb":"问方式用“怎么”。"}},{"id":"QH-012","level":"HSK 2","title":"这件衣服多少钱","scene":"买衣服","vocab":["件","衣服","多少","钱","贵","便宜","颜色","穿"],"dialogue":[{"s":"安","t":"这件衣服多少钱？"},{"s":"店","t":"三百块。"},{"s":"安","t":"太贵了，能便宜一点吗？"},{"s":"店","t":"那两百八吧，是最低价了。"},{"s":"安","t":"好，我要这件红色的。"},{"s":"店","t":"好的，请这边付钱。"}],"grammar":{"name":"多少钱；太……了","pattern":"X 多少钱？/ 太贵了。","explain":"问价格用“多少钱”；“太……了”表示程度超过预期。","examples":["这件衣服多少钱？","太贵了，能便宜一点吗？"],"practice":{"q":"觉得价格高，可以说：","opts":["太贵了","太便宜了"],"ans":0}},"listening":{"q":"这件衣服最后多少钱？","audio":"那两百八吧，是最低价了。","opts":["三百","两百八","两百"],"ans":1},"shadowing":"这件衣服多少钱？太贵了，能便宜一点吗？","quiz":{"q":"这件衣服 ___ 钱？","opts":["多少","什么","几"],"ans":0,"fb":"问价格用“多少钱”。"}},{"id":"QH-013","level":"HSK 2","title":"我比你早十分钟","scene":"比较到达时间","vocab":["比","早","晚","分钟","到","等","高兴","大家"],"dialogue":[{"s":"林","t":"你什么时候到的？"},{"s":"安","t":"我八点五十就到了，比你早十分钟。"},{"s":"林","t":"对不起，公交车晚点了。"},{"s":"安","t":"没关系，我等了不久。大家都到了吗？"},{"s":"林","t":"都到了，就等你呢。"},{"s":"安","t":"那我们快进去吧。"}],"grammar":{"name":"A 比 B + 形容词","pattern":"A 比 B + 形容词 +（数量）。","explain":"比较句：我比你早；可以加具体差距：我比你早十分钟。","examples":["我比你早十分钟。","地铁比公交快。"],"practice":{"q":"“8:50 到 vs 9:00 到”，正确说法是：","opts":["我比你早十分钟","我比你到十分钟"],"ans":0}},"listening":{"q":"林为什么迟到？","audio":"对不起，公交车晚点了。","opts":["起床晚了","公交车晚点","走错路了"],"ans":1},"shadowing":"我八点五十就到了，比你早十分钟。","quiz":{"q":"我 ___ 你早十分钟。","opts":["比","从","在"],"ans":0,"fb":"比较句用“比”。"}},{"id":"QH-014","level":"HSK 2","title":"你正在做什么","scene":"电话中的即时状态","vocab":["正在","呢","做饭","看书","电话","忙","睡觉"],"dialogue":[{"s":"安","t":"喂，你在做什么？"},{"s":"林","t":"我正在做饭呢。你呢？"},{"s":"安","t":"我在看书。你今天忙吗？"},{"s":"林","t":"不太忙，就做个晚饭。"},{"s":"安","t":"那我晚点再给你打电话。"},{"s":"林","t":"好，等我做完饭。"}],"grammar":{"name":"正在……呢","pattern":"正在 + 动词 +（呢）。","explain":"“正在……呢”强调动作此刻正在进行。","examples":["我正在做饭呢。","他正在睡觉。"],"practice":{"q":"“正在……呢”表示：","opts":["动作正在进行","动作已经完成"],"ans":0}},"listening":{"q":"安在做什么？","audio":"我在看书。你今天忙吗？","opts":["做饭","看书","打电话"],"ans":1},"shadowing":"我正在做饭呢，你呢？","quiz":{"q":"我 ___ 做饭呢。","opts":["正在","已经","刚"],"ans":0,"fb":"进行中用“正在……呢”。"}},{"id":"QH-015","level":"HSK 2","title":"周末一起看电影吧","scene":"邀请朋友","vocab":["周末","一起","电影","吧","可以","有空","去","地方"],"dialogue":[{"s":"安","t":"这个周末你有空吗？"},{"s":"林","t":"有空，怎么了？"},{"s":"安","t":"我们一起去看电影吧！"},{"s":"林","t":"好啊，星期六可以吗？"},{"s":"安","t":"可以，下午两点在电影院门口见。"},{"s":"林","t":"好，不见不散！"}],"grammar":{"name":"一起；吧；可以吗","pattern":"一起 + 动词 + 吧！/ 时间 + 可以吗？","explain":"“一起”表示共同行动；“吧”让建议更柔和；“可以吗”确认安排。","examples":["我们一起去看电影吧。","星期六可以吗？"],"practice":{"q":"发出邀请最自然的说法是：","opts":["一起去看电影吧","看电影一起吧去"],"ans":0}},"listening":{"q":"他们约在哪天见面？","audio":"好啊，星期六可以吗？","opts":["星期五","星期六","星期天"],"ans":1},"shadowing":"这个周末你有空吗？一起去看电影吧。","quiz":{"q":"我们一起去看电影 ___ ！","opts":["吧","吗","呢"],"ans":0,"fb":"建议句尾用“吧”。"}},{"id":"QH-016","level":"HSK 2","title":"我已经吃过了","scene":"回应吃饭邀请","vocab":["已经","过","吃","饭","饭店","菜","次","饱"],"dialogue":[{"s":"林","t":"我们去饭店吃饭吧？"},{"s":"安","t":"谢谢，我已经吃过了。"},{"s":"林","t":"那你吃过这家饭店的四川菜吗？"},{"s":"安","t":"吃过一次，很好吃！"},{"s":"林","t":"那下次我们一起去。"},{"s":"安","t":"好啊，下次一定去！"}],"grammar":{"name":"已经；过","pattern":"已经 + 动词 + 过 / 了。","explain":"“过”表示有过某种经历；“已经”强调事情完成。","examples":["我已经吃过了。","你吃过四川菜吗？"],"practice":{"q":"“我去 ___ 北京两次”表示经历，应该用：","opts":["过","了","正在"],"ans":0}},"listening":{"q":"安为什么不去饭店？","audio":"谢谢，我已经吃过了。","opts":["不喜欢那家店","已经吃过了","没有时间"],"ans":1},"shadowing":"我已经吃过了，下次我们一起去吧。","quiz":{"q":"我已经吃 ___ 了。","opts":["过","在","是"],"ans":0,"fb":"经历用“动词 + 过”。"}},{"id":"QH-017","level":"HSK 2","title":"离学校远不远","scene":"找住处","vocab":["离","远","近","公里","走","旁边","找","住"],"dialogue":[{"s":"安","t":"你现在住在哪儿？"},{"s":"林","t":"我住在学校旁边。"},{"s":"安","t":"离学校远不远？"},{"s":"林","t":"不远，走路十分钟就到。"},{"s":"安","t":"真方便！我还在找房子。"},{"s":"林","t":"那边有个地铁站，也很近。"}],"grammar":{"name":"离；远不远","pattern":"A 离 B + 远/近。/ 远不远？","explain":"“离”表示两地距离；正反疑问用“远不远”。","examples":["我家离学校不远。","你家离学校远不远？"],"practice":{"q":"“___学校不远”应该说：","opts":["离","从","到"],"ans":0}},"listening":{"q":"林家到学校怎么走？","audio":"不远，走路十分钟就到。","opts":["坐地铁","坐公交","走路"],"ans":2},"shadowing":"我住在学校旁边，走路十分钟就到。","quiz":{"q":"你家 ___ 学校远吗？","opts":["离","在","有"],"ans":0,"fb":"距离用“离”。"}},{"id":"QH-018","level":"HSK 2","title":"因为下雨，所以我没去","scene":"解释原因","vocab":["因为","所以","下雨","去","计划","取消","没关系","还是"],"dialogue":[{"s":"林","t":"昨天你怎么没来公园？"},{"s":"安","t":"因为下雨，所以我没去。"},{"s":"林","t":"没关系，活动也取消了。"},{"s":"安","t":"那真可惜。这个星期还去吗？"},{"s":"林","t":"如果不下雨，我们就去。"},{"s":"安","t":"好，希望周末不下雨。"}],"grammar":{"name":"因为……所以……","pattern":"因为 + 原因，所以 + 结果。","explain":"“因为”引出原因，“所以”引出结果，口语中可只用其一。","examples":["因为下雨，所以我没去。","因为他生病，所以没来上课。"],"practice":{"q":"“___ 下雨，___ 我没去”正确搭配是：","opts":["因为……所以……","虽然……但是……"],"ans":0}},"listening":{"q":"昨天活动怎么样了？","audio":"没关系，活动也取消了。","opts":["正常进行","取消了","改到下周"],"ans":1},"shadowing":"因为下雨，所以我没去公园。","quiz":{"q":"___ 下雨，所以我没去。","opts":["因为","所以","虽然"],"ans":0,"fb":"原因用“因为”。"}},{"id":"QH-019","level":"HSK 2","title":"他唱得很好","scene":"评价能力表现","vocab":["唱","得","好","运动","跑步","游泳","不错","慢慢"],"dialogue":[{"s":"安","t":"你会唱中文歌吗？"},{"s":"林","t":"会一点，我唱得不太好。"},{"s":"安","t":"没关系，你唱得很好！"},{"s":"林","t":"谢谢。你运动怎么样？"},{"s":"安","t":"我跑步跑得很快，游泳也不错。"},{"s":"林","t":"那我们周末去游泳吧！"}],"grammar":{"name":"动词 + 得 + 程度","pattern":"动词 + 得 + 好/快/不错。","explain":"用“得”评价动作做得怎么样：唱得好、跑得快。","examples":["他唱得很好。","她游泳游得不错。"],"practice":{"q":"评价别人的中文水平，可以说：","opts":["你中文说得很好","你中文很好说得"],"ans":0}},"listening":{"q":"安擅长什么运动？","audio":"我跑步跑得很快，游泳也不错。","opts":["跑步","游泳","跑步和游泳"],"ans":2},"shadowing":"他唱得很好，你中文说得也不错。","quiz":{"q":"他唱 ___ 很好。","opts":["得","的","地"],"ans":0,"fb":"程度补语用“得”。"}},{"id":"QH-020","level":"HSK 2","title":"我们去过上海","scene":"分享旅行经历","vocab":["过","上海","旅行","城市","景点","次","还没","照片"],"dialogue":[{"s":"林","t":"你去过上海吗？"},{"s":"安","t":"去过两次，上海是个很大的城市。"},{"s":"林","t":"我还没去过，有什么好玩的？"},{"s":"安","t":"有很多著名的景点，我还拍了很多照片。"},{"s":"林","t":"那我们下次一起去吧！"},{"s":"安","t":"好啊，我给你当向导。"}],"grammar":{"name":"过；还没……过","pattern":"动词 + 过。/ 还没 + 动词 + 过。","explain":"“过”表经历；否定用“还没……过”。","examples":["我们去过上海。","我还没去过北京。"],"practice":{"q":"“我 ___ 去过北京”表示从未去过，应该用：","opts":["还没","已经","正在"],"ans":0}},"listening":{"q":"安去过上海几次？","audio":"去过两次，上海是个很大的城市。","opts":["一次","两次","三次"],"ans":1},"shadowing":"我们去过上海两次，还拍了很多照片。","quiz":{"q":"我们去过 ___ 上海。","opts":["过","了","的"],"ans":0,"fb":"经历用“去过”。"}},{"id":"QH-021","level":"HSK 3","title":"我今天迟到了","scene":"上课迟到","vocab":["迟到","本来","地铁","特别","刚","关系","事"],"dialogue":[{"s":"林","t":"你怎么现在才来？"},{"s":"安","t":"不好意思，我迟到了。"},{"s":"林","t":"出什么事了？"},{"s":"安","t":"我本来想坐地铁，但是今天地铁的人特别多。"},{"s":"林","t":"没关系，我们也刚到。"}],"grammar":{"name":"本来……但是……","pattern":"本来 + 计划 / 情况，但是 + 实际变化","explain":"先说原来的计划或情况，再说明后来发生的变化。","examples":["我本来想坐地铁，但是今天人特别多。","我本来不想去，但是朋友请我一起去。"],"practice":{"q":"选择最自然的句子：","opts":["我本来想早点睡，但是晚上喝了咖啡。","我但是想早点睡，本来喝了咖啡。"],"ans":0}},"listening":{"q":"安娜为什么迟到了？","audio":"我本来想坐地铁，但是今天地铁的人特别多。","opts":["她起床太晚了","地铁里的人很多","她找不到地铁站"],"ans":1},"shadowing":"我本来想坐地铁，但是今天人特别多。","quiz":{"q":"我今天上课 ___ 了。","opts":["迟到","到迟","晚到"],"ans":0,"fb":"“迟到 + 了”表示迟到这件事已经发生。"}},{"id":"QH-022","level":"HSK 3","title":"快递已经到了","scene":"下楼取快递","vocab":["快递","收到","楼下","下来","上去","拿","箱子","已经"],"dialogue":[{"s":"安","t":"喂，你好，是 Alex 吗？你的快递已经到了。"},{"s":"林","t":"太好了！我现在下去拿。"},{"s":"安","t":"快递员就在楼下，请快一点。"},{"s":"林","t":"箱子大不大？要不要我帮你拿上去？"},{"s":"安","t":"不用，我自己可以。谢谢你！"},{"s":"林","t":"那我先上去了，楼下见。"}],"grammar":{"name":"趋向补语：来 / 去 / 上 / 下","pattern":"动词 + 来/去；动词 + 上/下 + 来/去","explain":"“来”朝说话人方向，“去”离说话人方向；上、下说明动作方向。","examples":["快递已经到了，我下楼去拿。","我把箱子拿上去了。"],"practice":{"q":"“快递员在楼下，你快 ___ 吧”应该说：","opts":["下去","上去"],"ans":0}},"listening":{"q":"快递在哪里？","audio":"快递员就在楼下，请快一点。","opts":["楼上","楼下","快递站"],"ans":1},"shadowing":"你的快递已经到了，我现在下楼去拿。","quiz":{"q":"快递已经到 ___ 。","opts":["了","着","过"],"ans":0,"fb":"完成用“了”。"}},{"id":"QH-023","level":"HSK 3","title":"我把护照忘在家了","scene":"出门发现遗漏","vocab":["把","护照","忘","忘记","带","检查","行李","机场"],"dialogue":[{"s":"安","t":"糟糕！我把护照忘在家了。"},{"s":"林","t":"真的吗？你检查过行李了吗？"},{"s":"安","t":"检查过两次，还是忘了。怎么办？"},{"s":"林","t":"别着急，我们回家拿，时间还够。"},{"s":"安","t":"太谢谢你了！"},{"s":"林","t":"以后出门前把护照放在包的最上面。"}],"grammar":{"name":"把字句","pattern":"把 + 东西 + 动词 + 结果/地点","explain":"“把”强调对物品的处理和结果：把护照忘在家了。","examples":["我把护照忘在家了。","请把门关上。"],"practice":{"q":"正确的把字句是：","opts":["我把护照忘在家了","我护照忘把在家了"],"ans":0}},"listening":{"q":"安出了什么问题？","audio":"糟糕！我把护照忘在家了。","opts":["丢了行李","忘了护照","走错了路"],"ans":1},"shadowing":"糟糕，我把护照忘在家了，我们回去拿吧。","quiz":{"q":"我 ___ 护照忘在家了。","opts":["把","被","在"],"ans":0,"fb":"处置物品用“把”。"}},{"id":"QH-024","level":"HSK 3","title":"最近越来越忙了","scene":"谈论近期变化","vocab":["最近","越来越","忙","习惯","变化","生活","天气","喜欢"],"dialogue":[{"s":"林","t":"好久不见！你最近怎么样？"},{"s":"安","t":"我最近越来越忙了，课也越来越多。"},{"s":"林","t":"习惯这里的生活了吗？"},{"s":"安","t":"习惯了，而且我越来越喜欢这座城市了。"},{"s":"林","t":"那就好。天气也越来越冷了，注意保暖。"},{"s":"安","t":"谢谢，你也是！"}],"grammar":{"name":"越来越……","pattern":"越来越 + 形容词/心理动词","explain":"表示程度随时间加深：越来越忙、越来越喜欢。","examples":["我最近越来越忙了。","天气越来越冷了。"],"practice":{"q":"“天气 ___ 冷了”表示逐渐变冷，应该用：","opts":["越来越","有一点"],"ans":0}},"listening":{"q":"安对这座城市的感觉怎么样？","audio":"习惯了，而且我越来越喜欢这座城市了。","opts":["不喜欢","越来越喜欢","想离开"],"ans":1},"shadowing":"我最近越来越忙了，但是越来越喜欢这里的生活。","quiz":{"q":"我最近 ___ 忙了。","opts":["越来越","刚才","已经"],"ans":0,"fb":"变化趋势用“越来越”。"}},{"id":"QH-025","level":"HSK 3","title":"先吃饭，然后开会","scene":"安排工作顺序","vocab":["先","然后","开会","准备","材料","安排","最后","结束"],"dialogue":[{"s":"林","t":"今天下午怎么安排？"},{"s":"安","t":"我们先吃饭，然后两点开会。"},{"s":"林","t":"开会的材料准备好了吗？"},{"s":"安","t":"准备好了。开完会，我们再去接客户。"},{"s":"林","t":"会议几点结束？"},{"s":"安","t":"大概五点结束，最后一起吃饭。"}],"grammar":{"name":"先……然后……","pattern":"先 + 动作1，然后 + 动作2","explain":"按顺序说明先后安排，可加“再”“最后”。","examples":["我们先吃饭，然后开会。","先做作业，然后看电视。"],"practice":{"q":"表示事情顺序应该用：","opts":["先吃饭，然后开会","然后吃饭，先开会"],"ans":0}},"listening":{"q":"开会前做什么？","audio":"我们先吃饭，然后两点开会。","opts":["接客户","吃饭","准备材料"],"ans":1},"shadowing":"我们先吃饭，然后两点开会。","quiz":{"q":"___ 吃饭，然后开会。","opts":["先","后","再"],"ans":0,"fb":"第一件事用“先”。"}},{"id":"QH-026","level":"HSK 3","title":"虽然下雨，但是我们去了","scene":"计划不受影响","vocab":["虽然","但是","出发","活动","坚持","还是","决定","淋"],"dialogue":[{"s":"林","t":"昨天下那么大的雨，你们还去爬山了？"},{"s":"安","t":"虽然下雨，但是我们还是去了。"},{"s":"林","t":"你们真有毅力！没被淋湿吗？"},{"s":"安","t":"有一点，但是大家玩得很开心。"},{"s":"林","t":"下次有活动叫上我。"},{"s":"安","t":"没问题，我们决定下个月再去一次。"}],"grammar":{"name":"虽然……但是……","pattern":"虽然 + 不利情况，但是 + 不变的决定/结果","explain":"先承认一个事实，再转折说明相反的结果。","examples":["虽然下雨，但是我们还是去了。","虽然很累，但是她没有休息。"],"practice":{"q":"“___ 很累，___ 他没有休息”正确搭配是：","opts":["虽然……但是……","因为……所以……"],"ans":0}},"listening":{"q":"昨天的活动怎么样？","audio":"虽然下雨，但是我们还是去了。","opts":["取消了","照常进行","改期了"],"ans":1},"shadowing":"虽然下雨，但是我们还是去了。","quiz":{"q":"___ 下雨，但是我们还是去了。","opts":["虽然","因为","如果"],"ans":0,"fb":"让步转折用“虽然……但是……”。"}},{"id":"QH-027","level":"HSK 3","title":"除了咖啡，我也喝茶","scene":"说明范围与补充","vocab":["除了","以外","也","茶","习惯","饮料","选择","健康"],"dialogue":[{"s":"林","t":"你平时喝什么饮料？"},{"s":"安","t":"除了咖啡，我也喝茶。"},{"s":"林","t":"我以为你只喝咖啡呢！"},{"s":"安","t":"不是，除了周末以外，我每天上午都喝茶。"},{"s":"林","t":"喝茶是个健康的习惯。"},{"s":"安","t":"对，这也是我的选择。"}],"grammar":{"name":"除了……以外，也……","pattern":"除了 A 以外，也/都 + 动词 B","explain":"“除了……也”表示包含；“除了……都（不）”表示排除。","examples":["除了咖啡，我也喝茶。","除了周末以外，我每天都上班。"],"practice":{"q":"“咖啡和茶都喝”应该说：","opts":["除了咖啡，我也喝茶","除了咖啡，我只喝茶"],"ans":0}},"listening":{"q":"安每天上午喝什么？","audio":"除了周末以外，我每天上午都喝茶。","opts":["咖啡","茶","果汁"],"ans":1},"shadowing":"除了咖啡，我也喝茶，这是个健康的习惯。","quiz":{"q":"___ 咖啡，我也喝茶。","opts":["除了","因为","虽然"],"ans":0,"fb":"补充范围用“除了……也”。"}},{"id":"QH-028","level":"HSK 3","title":"这件事被他发现了","scene":"描述意外结果","vocab":["被","发现","秘密","结果","偷","钥匙","丢","生气"],"dialogue":[{"s":"安","t":"怎么了？你看起来不太高兴。"},{"s":"林","t":"我的秘密被弟弟发现了。"},{"s":"安","t":"什么秘密？"},{"s":"林","t":"我给他准备的生日惊喜。现在他全知道了。"},{"s":"安","t":"哈哈，没关系，心意还在。"},{"s":"林","t":"也只能这样想了。"}],"grammar":{"name":"被字句","pattern":"东西/人 + 被 + 施动者 + 动词 + 结果","explain":"“被”引出动作的执行者，主语是承受者：秘密被他发现了。","examples":["这件事被他发现了。","我的自行车被偷了。"],"practice":{"q":"正确的被字句是：","opts":["秘密被他发现了","他被秘密发现了"],"ans":0}},"listening":{"q":"林为什么不高兴？","audio":"我的秘密被弟弟发现了。","opts":["丢了钥匙","秘密被发现","被雨淋了"],"ans":1},"shadowing":"这件事被他发现了，我有点生气。","quiz":{"q":"这件事 ___ 他发现了。","opts":["被","把","让"],"ans":0,"fb":"被动用“被”。"}},{"id":"QH-029","level":"HSK 3","title":"如果有时间，就去旅行","scene":"讨论条件计划","vocab":["如果","就","时间","旅行","假期","计划","条件","打算"],"dialogue":[{"s":"林","t":"假期你有什么计划？"},{"s":"安","t":"如果有时间，我就去旅行。"},{"s":"林","t":"打算去哪儿？"},{"s":"安","t":"如果机票便宜，就去云南；如果太贵，就在附近走走。"},{"s":"林","t":"好主意！如果时间允许，我也想一起去。"},{"s":"安","t":"那我们一起做计划吧。"}],"grammar":{"name":"如果……就……","pattern":"如果 + 条件，就 + 结果","explain":"“如果”提出假设条件，“就”引出该条件下的结果。","examples":["如果有时间，我就去旅行。","如果明天下雨，我就不去了。"],"practice":{"q":"“___ 有时间，我 ___ 去旅行”正确搭配是：","opts":["如果……就……","虽然……但是……"],"ans":0}},"listening":{"q":"安什么情况下会去云南？","audio":"如果机票便宜，就去云南。","opts":["机票便宜","天气好","朋友一起去"],"ans":0},"shadowing":"如果有时间，我就去旅行。","quiz":{"q":"___ 有时间，就去旅行。","opts":["如果","虽然","因为"],"ans":0,"fb":"条件假设用“如果……就”。"}},{"id":"QH-030","level":"HSK 3","title":"我终于找到新工作了","scene":"分享过程和结果","vocab":["终于","找到","工作","面试","努力","机会","成功","告诉"],"dialogue":[{"s":"安","t":"告诉你一个好消息：我终于找到新工作了！"},{"s":"林","t":"太好了！面试了几次？"},{"s":"安","t":"一共面试了三次，最后一次终于成功了。"},{"s":"林","t":"你一直那么努力，这是你应得的机会。"},{"s":"安","t":"谢谢！下星期一开始上班。"},{"s":"林","t":"那我们周末好好庆祝一下！"}],"grammar":{"name":"终于；结果补语","pattern":"经过长时间/努力，终于 + 动词 + 结果","explain":"“终于”强调期待已久的结果终于出现；“到/完/好”等结果补语说明动作完成。","examples":["我终于找到新工作了。","我们终于完成了这个项目。"],"practice":{"q":"“___ 找到新工作了”强调等待已久，应该用：","opts":["终于","马上"],"ans":0}},"listening":{"q":"安面试了几次？","audio":"一共面试了三次，最后一次终于成功了。","opts":["一次","两次","三次"],"ans":2},"shadowing":"我终于找到新工作了，面试了三次才成功。","quiz":{"q":"我 ___ 找到新工作了。","opts":["终于","刚刚","马上"],"ans":0,"fb":"期待已久的结果用“终于”。"}}];
